function RECIPROCITY_SOLVE(hbar, energy?, time?):
    require exactly one of {energy, time} is given
    if time given:
        E <- hbar / time
        assert |hbar / E - time| <= eps * |time|   # involutivity
        return (E, time)
    else:
        t <- hbar / energy
        assert |hbar / t - energy| <= eps * |energy|
        return (energy, t)

function CROSSOVER_TUBULINS(hbar, E, t_target):
    # solve hbar / (E * sqrt(N)) = t_target for N
    return (hbar / (E * t_target))^2

function FALLS_BELOW(hbar, E, N, t_target):
    return hbar / (E * sqrt(N)) < t_target

function DIAGONAL_WITNESS(T, index):
    D <- empty set
    for x in T:
        if x not in index(x):
            add x to D
    return D            # D is never in range(index)

function IS_UNNAMED(T, index, D):
    return for all x in T: index(x) != D

